// Le site envoie { reference: "MP-..." } quand l'utilisateur valide ses repas.
const body = $input.first().json.body || {};
const ref = (body.reference || '').trim();

if (!ref) {
  return [{ json: { valide: false, reference: '' } }];
}
return [{ json: { valide: true, reference: ref } }];

// Builds the shopping list IN CODE, then asks Groq only for aisle, price, pantry match.
// Merging: names are normalised ("fresh parsley leaves" -> "parsley", "tomatoes" -> "tomato"),
// then every unit of the same ingredient is converted to ONE unit (g, ml or pieces)
// using typical densities and piece weights, so each ingredient appears once.

const demande = $('Find Request').first().json;
let brut = {}; try { brut = JSON.parse(demande['Payload brut'] || '{}'); } catch (e) {}
const FR = brut.lang === 'fr';
const lignes = $input.all().map(function (i) { return i.json; });

// ---------- 1. Name normalisation ----------
const SYNONYMES = {
  'cilantro': 'coriander', 'scallion': 'spring onion', 'green onion': 'spring onion', 'garbanzo bean': 'chickpea',
  'capsicum': 'bell pepper', 'aubergine': 'eggplant', 'courgette': 'zucchini', 'garlic clove': 'garlic',
  'italian parsley': 'parsley', 'flat leaf parsley': 'parsley', 'kosher salt': 'salt', 'sea salt': 'salt', 'table salt': 'salt',
  'extra virgin olive oil': 'olive oil', 'evoo': 'olive oil', 'plain flour': 'flour', 'all purpose flour': 'flour',
  'caster sugar': 'sugar', 'granulated sugar': 'sugar', 'white sugar': 'sugar', 'unsalted butter': 'butter', 'salted butter': 'butter',
  'boneless skinless chicken breast': 'chicken breast', 'skinless chicken breast': 'chicken breast', 'boneless chicken breast': 'chicken breast',
  'chicken stock': 'chicken broth', 'vegetable stock': 'vegetable broth', 'beef stock': 'beef broth', 'black peppercorn': 'black pepper',
  'ground black pepper': 'black pepper', 'pepper': 'black pepper'
};
const MOTS_INUTILES = ['fresh', 'freshly', 'chopped', 'minced', 'sliced', 'diced', 'finely', 'roughly', 'coarsely', 'grated', 'shredded',
  'leaves', 'leaf', 'sprigs', 'sprig', 'large', 'medium', 'small', 'whole', 'raw', 'organic', 'ripe', 'peeled', 'crushed', 'cloves', 'clove',
  'handful', 'bunch', 'of', 'to', 'taste', 'optional', 'flat-leaf', 'packed', 'thinly', 'halved', 'cubed', 'trimmed'];
const PAS_DE_PLURIEL = ['asparagus', 'hummus', 'couscous', 'molasses', 'swiss', 'grass', 'lemongrass', 'bass', 'citrus', 'hibiscus', 'watercress', 'cress'];

function singulier(mot) {
  if (PAS_DE_PLURIEL.indexOf(mot) !== -1 || mot.length <= 3) return mot;
  if (/ies$/.test(mot)) return mot.slice(0, -3) + 'y';
  if (/(tomato|potato|mango)es$/.test(mot)) return mot.slice(0, -2);
  if (/(ch|sh)es$/.test(mot)) return mot.slice(0, -2);
  if (/[^s]s$/.test(mot)) return mot.slice(0, -1);
  return mot;
}
function normaliserNom(brut) {
  let n = String(brut || '').toLowerCase().replace(/\(.*?\)/g, ' ').replace(/[^a-zà-ÿ\s-]/g, ' ').replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
  if (SYNONYMES[n]) return SYNONYMES[n];
  let mots = n.split(' ').filter(function (m) { return MOTS_INUTILES.indexOf(m) === -1; });
  if (!mots.length) mots = n.split(' ');
  mots[mots.length - 1] = singulier(mots[mots.length - 1]);
  n = mots.join(' ');
  if (/^ground /.test(n) && !/(beef|pork|turkey|chicken|lamb|meat)/.test(n)) n = n.replace(/^ground /, '');
  return SYNONYMES[n] || n;
}

// ---------- 2. Units ----------
const VERS_ML = { tsp: 5, tsps: 5, teaspoon: 5, teaspoons: 5, t: 5, tbsp: 15, tbsps: 15, tablespoon: 15, tablespoons: 15, tbs: 15, T: 15,
  cup: 240, cups: 240, ml: 1, milliliter: 1, milliliters: 1, cl: 10, dl: 100, l: 1000, liter: 1000, liters: 1000, 'fl oz': 30, dash: 0.6, pinch: 0.3, pinches: 0.3 };
const VERS_G = { g: 1, gram: 1, grams: 1, kg: 1000, oz: 28.35, ounce: 28.35, ounces: 28.35, lb: 454, lbs: 454, pound: 454, pounds: 454 };
const PIECES = ['', 'piece', 'pieces', 'serving', 'servings', 'large', 'medium', 'small', 'whole', 'clove', 'cloves', 'head', 'heads', 'can', 'cans',
  'slice', 'slices', 'stalk', 'stalks', 'fillet', 'fillets', 'bunch', 'bunches', 'handful', 'handfuls', 'sprig', 'sprigs', 'leaf', 'leaves'];

// Grams per ml for common ingredients (default 1).
const DENSITES = [
  [/parsley|coriander|basil|mint|dill|chive|tarragon|thyme|rosemary|oregano|sage|herb|spinach|rocket|arugula|lettuce/, 0.12],
  [/cumin|paprika|cinnamon|turmeric|curry powder|chili powder|chilli powder|garam masala|nutmeg|ginger powder|powder|spice|seasoning|black pepper/, 0.5],
  [/flour|cocoa|breadcrumb|panko/, 0.55], [/oat/, 0.4], [/sugar/, 0.85], [/salt/, 1.2], [/honey|syrup|molasses/, 1.4],
  [/rice|lentil|quinoa|couscous/, 0.8], [/cheese|parmesan|cheddar|feta|mozzarella/, 0.45], [/butter/, 0.95], [/nut|almond|walnut|cashew|seed/, 0.6]
];
function densite(nom) { for (let i = 0; i < DENSITES.length; i++) if (DENSITES[i][0].test(nom)) return DENSITES[i][1]; return 1; }
const LIQUIDE = /milk|water|broth|stock|cream|juice|vinegar|oil|wine|sauce|syrup|beer|coconut milk/;

// Typical weight of one piece, in grams (for items people buy by the piece).
const POIDS_PIECE = [
  [/^garlic$/, 5], [/spring onion/, 15], [/red onion|onion/, 150], [/shallot/, 40], [/egg$/, 55], [/lemon/, 100], [/lime/, 65], [/orange/, 130],
  [/cherry tomato/, 15], [/tomato/, 120], [/sweet potato/, 250], [/potato/, 170], [/carrot/, 70], [/bell pepper/, 150], [/zucchini/, 200],
  [/cucumber/, 300], [/avocado/, 170], [/banana/, 120], [/apple/, 180], [/chili|chilli|jalapeno/, 15], [/eggplant/, 300],
  [/chicken breast/, 170], [/chicken thigh/, 110], [/mushroom/, 18], [/celery/, 40], [/leek/, 200], [/cabbage/, 900], [/broccoli/, 350],
  [/cauliflower/, 600], [/tortilla/, 45], [/pita|naan|bun|bagel/, 70], [/salmon fillet|fish fillet|cod fillet/, 140], [/can$|canned/, 400]
];
function poidsPiece(nom) { for (let i = 0; i < POIDS_PIECE.length; i++) if (POIDS_PIECE[i][0].test(nom)) return POIDS_PIECE[i][1]; return 0; }

// ---------- 3. Merge ----------
const fusion = {};
lignes.forEach(function (r) {
  let ing = [];
  try { ing = JSON.parse(r.Ingredients || '[]'); } catch (e) { ing = []; }
  const plat = String(r.Plat || '').split(/\s+/).slice(0, 3).join(' ');
  ing.forEach(function (i) {
    const nom = normaliserNom(i.nom);
    if (!nom) return;
    const q = Number(i.quantite) || 0;
    const u = String(i.unite || '').trim();
    const ul = u.toLowerCase();
    if (!fusion[nom]) fusion[nom] = { g: 0, ml: 0, pieces: 0, autres: {}, plats: [] };
    const f = fusion[nom];
    if (VERS_G[ul] !== undefined) f.g += q * VERS_G[ul];
    else if (VERS_ML[u] !== undefined || VERS_ML[ul] !== undefined) f.ml += q * (VERS_ML[u] !== undefined ? VERS_ML[u] : VERS_ML[ul]);
    else if (PIECES.indexOf(ul) !== -1) {
      if (/^cans?$/.test(ul)) f.g += q * 400;
      else if (/^bunch/.test(ul)) f.g += q * 30;
      else if (/^handful/.test(ul)) f.g += q * 30;
      else if (/^(sprig|leaf|leaves)/.test(ul)) f.g += q * 1;
      else f.pieces += q;
    } else { f.autres[ul] = (f.autres[ul] || 0) + q; }
    if (f.plats.indexOf(plat) === -1) f.plats.push(plat);
  });
});

function arrondirMasse(v, u) {
  let x = v < 50 ? Math.ceil(v / 5) * 5 : Math.ceil(v / 10) * 10;
  x = Math.max(x, 5);
  if (x >= 1000) return (Math.round(x / 100) / 10) + (u === 'g' ? ' kg' : ' L');
  return x + ' ' + u;
}

const articles = Object.keys(fusion).map(function (nom) {
  const f = fusion[nom];
  const liquide = LIQUIDE.test(nom);
  const d = densite(nom);
  const pp = poidsPiece(nom);
  // Everything that can become one unit does.
  let masse = f.g + (liquide ? 0 : f.ml * d);
  let volume = liquide ? f.ml + f.g / d : 0;
  let pieces = f.pieces;
  const parts = [];
  if (pp && (pieces || masse)) {
    // Bought by the piece: express the whole amount as a piece count.
    const total = pieces * pp + masse;
    parts.push(Math.max(1, Math.ceil(total / pp)) + (nom === 'garlic' ? ' cloves' : ' pieces'));
    masse = 0; pieces = 0;
  }
  if (pieces && masse) { masse += 0; parts.push(Math.ceil(pieces) + ' pieces'); pieces = 0; }
  if (masse) parts.push(arrondirMasse(masse, 'g'));
  if (volume) parts.push(arrondirMasse(volume, 'ml'));
  if (pieces) parts.push(Math.ceil(pieces) + ' pieces');
  Object.keys(f.autres).forEach(function (u) { parts.push(Math.ceil(f.autres[u]) + ' ' + u); });
  return { ingredient: nom, quantite: parts.join(' + ') || 'to taste', utilise_dans: f.plats.join(', ') };
});

if (articles.length === 0) {
  return [{ json: { echec: true, raison: 'Aucun ingrédient trouvé dans les repas', recordId: demande.id } }];
}

// ---------- 4. Small prompt: aisle, price, pantry ----------
const liste = articles.map(function (a, i) { return i + '. ' + a.ingredient + ' (' + a.quantite + ')'; }).join('\n');
const prompt = [
  "For each numbered grocery item below, give its supermarket aisle, an estimated price in euros (average French supermarket, for the quantity shown), and whether it is already in the pantry.",
  "Pantry: " + (demande.Stock || 'nothing'),
  "Aisles allowed: fruits_legumes, viande_poisson, cremerie, epicerie, surgele, autre.",
  FR ? "Also give \"nom\": the item's usual French name as written on a shopping list (e.g. persil, oignon rouge)." : null,
  "",
  liste,
  "",
  "Answer ONLY with a JSON object in this exact format, one entry per item number:",
  FR ? '{"items":[{"i":0,"nom":"riz","rayon":"epicerie","prix":1.2,"en_stock":false}]}' : '{"items":[{"i":0,"rayon":"epicerie","prix":1.2,"en_stock":false}]}'
].filter(function (l) { return l !== null; }).join('\n');

return [{ json: {
  reference: demande.Reference, recordId: demande.id, stock: demande.Stock || '', articles: articles, lang: FR ? 'fr' : 'en',
  corpsLLM: {
    model: 'openai/gpt-oss-120b', max_tokens: 8000, reasoning_effort: 'low', temperature: 0.2,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: 'You are a grocery assistant. You always answer with a single valid JSON object and nothing else.' },
      { role: 'user', content: prompt }
    ]
  }
} }];

// Merges Groq's aisle/price/pantry answers with the list built in code.
// If Groq skips an item, sensible defaults apply instead of failing.

const ctx = $('Merge Ingredients').first().json;
const rep = $input.first().json;

function echec(raison) {
  return [{ json: { echec: true, raison: raison, recordId: ctx.recordId } }];
}

let infos = {};
const choix = (rep.choices || [])[0];

if (rep.error) {
  return echec('Groq : ' + (rep.error.message || JSON.stringify(rep.error)).slice(0, 200));
}
if (choix && choix.message) {
  try {
    const texte = String(choix.message.content || '').replace(/```json|```/g, '').trim();
    const sortie = JSON.parse(texte);
    (sortie.items || []).forEach(function (x) { if (x && x.i !== undefined) infos[Number(x.i)] = x; });
  } catch (e) {
    infos = {}; // fall back to defaults below
  }
}

const RAYONS = ['fruits_legumes', 'viande_poisson', 'cremerie', 'epicerie', 'surgele', 'autre'];
const stock = String(ctx.stock || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(Boolean);

return ctx.articles.map(function (a, idx) {
  const x = infos[idx] || {};
  const dansStock = x.en_stock === true || stock.some(function (s) { return a.ingredient.indexOf(s) !== -1 || s.indexOf(a.ingredient) !== -1; });
  return {
    json: {
      "Ingredient": (ctx.lang === 'fr' && x.nom) ? String(x.nom) : a.ingredient,
      "Quantite": a.quantite,
      "Rayon": RAYONS.indexOf(x.rayon) !== -1 ? x.rayon : 'autre',
      "Deja en stock": dansStock,
      "A acheter": !dansStock,
      "Cout estime": dansStock ? 0 : (Number(x.prix) || 0),
      "Utilise dans": a.utilise_dans,
      "Demande": ctx.reference
    }
  };
});

// Returns one item per existing shopping-list row (to delete before rebuilding),
// or a single marker item when there is none, so the flow never stops here.
const lignes = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.id && r.Ingredient; });
if (lignes.length === 0) return [{ json: { aucune: true } }];
return lignes.map(function (r) { return { json: { id: r.id } }; });
